const input = $input.first().json.body || $input.first().json;
const { question, answer, resumeText, jdText, history, blueprint, competencyIds, questionType, isAlreadyFollowUp } = input;
const truncate = (text, max) => !text ? '' : text.length > max ? text.slice(0, max) + '...[truncated]' : text;
const historyText = (history || []).slice(-4).map((item, index) => `Q${index + 1}: ${item.question}\nA${index + 1}: ${item.answer || '(no response)'}`).join('\n\n');
const competencies = (blueprint?.competencies || []).filter(item => (competencyIds || []).includes(item.id));
const prompt = `You are evaluating a candidate's answer during a live interview.

Current question: "${question}"
Question type: ${questionType}
Is this question already a follow-up: ${isAlreadyFollowUp ? 'yes' : 'no'}
Candidate answer: "${answer || '(no answer)'}"

Resume:
"""
${truncate(resumeText, 2500)}
"""
Job description:
"""
${truncate(jdText, 1500)}
"""
Recent history:
${historyText || 'None'}
Target competencies:
${competencies.length ? JSON.stringify(competencies) : 'None specified'}

Choose exactly one outcome.

advance: use for a sufficient primary technical answer; ANY answer to a follow-up; ANY non-technical answer; honest uncertainty; or when uncertain.
follow_up: use only for a relevant but materially insufficient PRIMARY technical answer, where one exact missing technical detail can be probed.
rephrase_primary: use only for a PRIMARY technical answer when the candidate asks for clarification, does not understand, or answers off-topic. The same competency must be asked again in simpler, more concrete language.

Hard rules:
- Never select follow_up or rephrase_primary for a non-technical question.
- Never select follow_up or rephrase_primary when this is already a follow-up.
- Do not penalise honest uncertainty or a short but relevant answer.
- If unsure, choose advance.
- For follow_up, identify one missing technical detail only.
- For rephrase_primary, state how to make the same question clearer without changing what it evaluates.

Return ONLY valid JSON:
{
  "recommended_action": "advance" | "follow_up" | "rephrase_primary",
  "authenticity_signal": "genuine" | "vague" | "suspicious" | "inconsistent",
  "depth_signal": "deep" | "surface" | "empty",
  "note": "Balanced internal recruiter note, maximum two sentences.",
  "follow_up_prompted": true | false,
  "insufficiency_reason": "lacks_depth" | "lacks_evidence" | "vague" | "irrelevant" | null,
  "follow_up_direction": "One specific technical detail to probe, or null.",
  "rephrase_direction": "How to restate the original question more clearly, or null.",
  "answer_was_irrelevant": true | false,
  "confidence": 0,
  "competency_evidence": []
}`;
return [{ json: { prompt } }];

const input = $input.first().json.body || $input.first().json;
const { resumeText, jdText, history, lastAssessmentNote, planItem, targetQuestion } = input;
const truncate = (text, max) => !text ? '' : text.length > max ? text.slice(0, max) + '...[truncated]' : text;
const recentHistory = (history || []).slice(-3);
const historyText = recentHistory.length ? recentHistory.map(item => `Q: ${item.question}\nA: ${item.answer || '(no response)'}`).join('\n\n') : 'None - this is the opening turn.';
const lastAnswer = recentHistory[recentHistory.length - 1]?.answer || '';
const turnIntent = lastAssessmentNote?.recommended_action === 'follow_up' ? 'follow_up' : lastAssessmentNote?.recommended_action === 'rephrase_primary' ? 'rephrase_primary' : 'advance';
const questionType = planItem?.question_type || 'technical';
const focus = planItem?.objective || 'Ask one role-relevant question grounded in the resume and job description.';
const prompt = `You are Alex, a warm and professional technical recruiter.

Write the next interviewer turn as two strictly separate fields.

Candidate's most recent answer: "${lastAnswer || '(no prior answer)'}"
Interview outcome: ${turnIntent}
Next question supplied by the interview system: "${targetQuestion || ''}"
Focus if a new question is needed: ${focus}

Resume:
"""
${truncate(resumeText, 1800)}
"""
Job description:
"""
${truncate(jdText, 1000)}
"""
Recent conversation:
${historyText}

interviewer_text rules:
- It is an acknowledgement only: one or two warm, natural sentences.
- It MUST NOT contain a question, a question mark, or any wording from the next question.
- Do not praise, score, criticise, summarise, or expose internal analysis.
- Avoid hollow approval such as "Great answer", "Excellent", "Perfect", or "Wonderful".
- For advance, acknowledge neutrally and signal a smooth transition.
- For follow_up, acknowledge neutrally without implying the answer was insufficient.
- For rephrase_primary, acknowledge the clarification or pivot without blame.

question_text rules:
- It contains only one question and no acknowledgement or lead-in.
- If a next question was supplied, use it exactly as question_text.
- Otherwise write one specific role-relevant question.
- Never combine questions or invent resume experience.

Return ONLY valid JSON:
{
  "interviewer_text": "Acknowledgement only, with no question mark.",
  "question_text": "One question only, with no acknowledgement.",
  "turn_type": "question" | "follow_up",
  "question_type": "${questionType}",
  "should_continue": true
}`;
return [{ json: { prompt } }];

const input = $input.first().json.body || $input.first().json;
const { resumeText, jdText } = input;
const truncate = (t, max) => !t ? '' : t.length > max ? t.slice(0, max) + '...[truncated]' : t;
const prompt = `You are a senior technical recruiter analyzing the alignment between a candidate's resume and a job description.
Your goal is to detect GENUINE gaps — domain mismatches, experience-level gaps, or stack discrepancies.

RULES:
1. ONLY flag genuine, real gaps (e.g. non-technical background applying for senior engineer, 2-year candidate for 8+ year role).
2. DO NOT invent gaps if the candidate is well-matched — return [] for flagged_gaps.
3. probe_direction MUST be warm, respectful, curious, and non-accusatory.

Job Description:
"""
${truncate(jdText, 3000)}
"""

Candidate Resume:
"""
${truncate(resumeText, 3000)}
"""

Return ONLY JSON:
{
  "domain_alignment": "aligned" | "partial" | "mismatched",
  "domain_reasoning": "string",
  "experience_gap": {
    "jd_required_years": number | null,
    "candidate_years": number | null,
    "status": "underqualified" | "overqualified" | "aligned" | "unclear",
    "reasoning": "string"
  },
  "flagged_gaps": [
    {
      "gap_type": "domain_mismatch" | "experience_mismatch" | "stack_mismatch" | "seniority_mismatch",
      "description": "1-sentence description",
      "probe_direction": "warm, curious, non-accusatory probe direction"
    }
  ]
}`;
return [{ json: { prompt } }];

const input = $input.first().json.body || $input.first().json;
const { sessionId, resumeText, jdText, extractedTools, flaggedGaps } = input;
