TARGET COMPOSITION (EXACTLY 10 QUESTIONS):
1. technical_jd (4-7): JD-required named tools (must_have first).
2. technical_resume (0-1): candidate's resume-only tool depth. Skip if none.
3. gap_probe (0-2): ONLY if real gaps exist. Do NOT invent. Convert unused slots to technical_jd.
4. problem_solving (1): scenario/case-based reasoning (no target_tool).
5. cultural (2): work style, teamwork, collaboration.

RULES:
- Competencies map to SPECIFIC named tools (e.g. "React", "PostgreSQL").
- Difficulty: "foundation" or "applied" only.
${toolsContext}
${gapsContext}

Job description:
"""
${truncate(jdText, 3000)}
"""
Resume:
"""
${truncate(resumeText, 3000)}
"""

Return ONLY JSON:
{
  "competencies": [{"id":"kebab-id","name":"TOOL NAME","weight":1,"description":"string","expected_evidence":["string"]}],
  "question_plan": [
    {
      "id": "plan-1",
      "category": "technical_jd|technical_resume|gap_probe|problem_solving|cultural",
      "competency_ids": ["id"],
      "target_tool": "React",
      "verification_mode": "verify_claim|baseline_check",
      "objective": "string",
      "question_type": "technical|behavioral|situational|cultural",
      "difficulty": "foundation|applied",
      "gap_ref": { "gap_type": "domain_mismatch", "description": "string", "probe_direction": "string" }
    }
  ],
  "candidate_summary": {"strengths":["string"],"gaps":["string"],"claims_to_validate":["string"]},
  "constraints": {"max_primary_questions":10,"max_follow_ups_per_question":1}
}`;
return [{ json: { prompt } }];

